"""A collection of tools which simulates utility functions.

Ported from ToolSandbox ``tools/utilities.py``: timestamp math, unit conversion
(``pint``), lat/lon distance (``geopy``), and US holiday lookup (``holidays``).
``search_holiday`` still simulates a web-backed tool by requiring wifi.
"""

import datetime
from typing import Dict, Literal, Optional, cast

import geopy.distance  # type: ignore
import holidays
import pint
from pint import UndefinedUnitError
from rapidfuzz import fuzz, utils

from .setting import get_wifi_status
from .validators import (
    typechecked,
    validate_latitude,
    validate_longitude,
    validate_timestamp,
)


@typechecked
def get_current_timestamp() -> float:
    """Get current POSIX timestamp."""
    return datetime.datetime.now().timestamp()


@typechecked
def timestamp_to_datetime_info(
    timestamp: float,
) -> Dict[Literal["year", "month", "day", "hour", "minute", "second", "isoweekday"], int]:
    """Convert POSIX timestamp to a dictionary of date time information."""
    validate_timestamp(timestamp, "timestamp", float)
    target_datetime = datetime.datetime.fromtimestamp(timestamp)
    return {
        "year": target_datetime.year,
        "month": target_datetime.month,
        "day": target_datetime.day,
        "hour": target_datetime.hour,
        "minute": target_datetime.minute,
        "second": target_datetime.second,
        "isoweekday": target_datetime.isoweekday(),
    }


@typechecked
def datetime_info_to_timestamp(
    year: int, month: int, day: int, hour: int, minute: int, second: int
) -> float:
    """Convert date time information to POSIX timestamp."""
    return datetime.datetime(
        year=year, month=month, day=day, hour=hour, minute=minute, second=second
    ).timestamp()


@typechecked
def shift_timestamp(
    timestamp: float,
    weeks: int = 0,
    days: int = 0,
    hours: int = 0,
    minutes: int = 0,
    seconds: int = 0,
) -> float:
    """Shift a POSIX timestamp by the provided deltas (may be negative)."""
    validate_timestamp(timestamp, "timestamp", float)
    target_datetime = datetime.datetime.fromtimestamp(timestamp) + datetime.timedelta(
        weeks=weeks, days=days, hours=hours, minutes=minutes, seconds=seconds
    )
    return target_datetime.timestamp()


@typechecked
def timestamp_diff(
    timestamp_0: float, timestamp_1: float
) -> Dict[Literal["days", "seconds"], int]:
    """Return timestamp_1 - timestamp_0 represented in days and seconds."""
    validate_timestamp(timestamp_0, "timestamp_0", float)
    validate_timestamp(timestamp_1, "timestamp_1", float)
    time_delta = datetime.datetime.fromtimestamp(timestamp_1) - datetime.datetime.fromtimestamp(
        timestamp_0
    )
    return {"days": time_delta.days, "seconds": time_delta.seconds}


@typechecked
def seconds_to_hours_minutes_seconds(
    seconds: float,
) -> Dict[Literal["hour", "minute", "second"], int]:
    """Convert total seconds past 0:00 into hours, minutes and seconds."""
    target_datetime = datetime.datetime.fromtimestamp(seconds)
    return {
        "hour": target_datetime.hour,
        "minute": target_datetime.minute,
        "second": target_datetime.second,
    }


@typechecked
def unit_conversion(amount: float, from_unit: str, to_unit: str) -> float:
    """Convert an amount from one unit to another (common English unit names).

    Raises:
        UndefinedUnitError: If unable to parse the unit names provided
        ValueError:         If unable to convert between provided units
    """
    try:
        return cast(float, pint.Quantity(amount, from_unit).to(to_unit).magnitude)
    except UndefinedUnitError:
        return cast(
            float, pint.Quantity(amount, from_unit.lower()).to(to_unit.lower()).magnitude
        )


@typechecked
def calculate_lat_lon_distance(
    latitude_0: float, longitude_0: float, latitude_1: float, longitude_1: float
) -> float:
    """Calculate the distance in kilometers between 2 lat/lon pairs."""
    validate_latitude(latitude_0, name="latitude_0", expected_type=float)
    validate_latitude(latitude_1, name="latitude_1", expected_type=float)
    validate_longitude(longitude_0, name="longitude_0", expected_type=float)
    validate_longitude(longitude_1, name="longitude_1", expected_type=float)
    return cast(
        float,
        geopy.distance.distance(
            (latitude_0, longitude_0), (latitude_1, longitude_1)
        ).kilometers,
    )


@typechecked
def search_holiday(holiday_name: str, year: Optional[int] = None) -> Optional[float]:
    """Search for a US holiday by name; return its POSIX timestamp or None.

    Simulates a web-backed tool by requiring wifi.

    Raises:
        ConnectionError: If wifi is not enabled
    """
    if not get_wifi_status():
        raise ConnectionError("Wifi is not enabled")
    if year is None:
        year = datetime.datetime.now().year
    holiday_matches = sorted(
        (
            (
                fuzz.partial_ratio(holiday_name, name, processor=utils.default_process),
                date,
                name,
            )
            for date, name in holidays.country_holidays(country="US", years=year).items()
        ),
        reverse=True,
    )
    if holiday_matches and holiday_matches[0][0] > 90:
        return datetime.datetime.combine(
            holiday_matches[0][1], datetime.datetime.min.time()
        ).timestamp()
    return None

"""A collection of tools which simulates common functions used for settings.

Ported from ToolSandbox ``tools/setting.py``. Device settings are a single row
in the ``device_settings`` table.
"""

from typing import Dict, Literal, cast

from . import db
from .validators import validate_type

_BOOLEAN_SETTINGS = {"cellular", "wifi", "location_service", "low_battery_mode"}


def _require_settings() -> Dict[str, object]:
    row = db.get_settings_row()
    if row is None:
        raise KeyError("No device settings row found")
    return row


def set_boolean_settings(setting_name: str, on: bool) -> None:
    """Utility for setting boolean settings. Not exposed as a tool.

    Raises:
        KeyError:   If setting_name is not a boolean setting column
        ValueError: If the setting is already in the requested state
    """
    validate_type(setting_name, "setting_name", str)
    validate_type(on, "on", bool)

    row = _require_settings()
    if setting_name not in _BOOLEAN_SETTINGS:
        raise KeyError(f"{setting_name} is not a boolean column")
    if bool(row[setting_name]) == on:
        raise ValueError(f"{setting_name} already {('disabled', 'enabled')[int(on)]}")
    db.update("device_settings", "device_id", cast(str, row["device_id"]), {setting_name: on})


def get_boolean_settings(setting_name: str) -> bool:
    """Utility for getting boolean settings. Not exposed as a tool.

    Raises:
        KeyError:   If setting_name is not a boolean setting column
    """
    validate_type(setting_name, "setting_name", str)
    row = _require_settings()
    if setting_name not in _BOOLEAN_SETTINGS:
        raise KeyError(f"{setting_name} is not a boolean column")
    return bool(row[setting_name])


def set_low_battery_mode_status(on: bool) -> None:
    """Enable / Disable low battery mode.

    Raises:
        ValueError: If low battery mode is already turned on / off
    """
    validate_type(on, "on", bool)
    set_boolean_settings(setting_name="low_battery_mode", on=on)
    # Automatically turn off dependent services when low battery mode is on.
    if on:
        for dependent_setting in ["cellular", "wifi", "location_service"]:
            try:
                set_boolean_settings(dependent_setting, on=False)
            except ValueError:
                pass


def get_low_battery_mode_status() -> bool:
    """Request low battery mode status."""
    return get_boolean_settings("low_battery_mode")


def set_location_service_status(on: bool) -> None:
    """Enable / Disable location service.

    Raises:
        ValueError:      If location service is already turned on / off
        PermissionError: If low battery mode is on
    """
    if on and get_low_battery_mode_status():
        raise PermissionError("Location service cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="location_service", on=on)


def get_location_service_status() -> bool:
    """Request location service status."""
    return get_boolean_settings("location_service")


def set_cellular_service_status(on: bool) -> None:
    """Enable / Disable cellular service.

    Raises:
        ValueError:      If cellular service is already turned on / off
        PermissionError: If low battery mode is on
    """
    validate_type(on, "on", bool)
    if on and get_low_battery_mode_status():
        raise PermissionError("Cellular service cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="cellular", on=on)


def get_cellular_service_status() -> bool:
    """Request cellular service status."""
    return get_boolean_settings("cellular")


def set_wifi_status(on: bool) -> None:
    """Enable / Disable wifi.

    Raises:
        ValueError:      If wifi is already turned on / off
        PermissionError: If low battery mode is on
    """
    validate_type(on, "on", bool)
    if on and get_low_battery_mode_status():
        raise PermissionError("Wifi cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="wifi", on=on)


def get_wifi_status() -> bool:
    """Request wifi status."""
    return get_boolean_settings("wifi")


def get_current_location() -> Dict[Literal["latitude", "longitude"], float]:
    """Request current location latitude and longitude.

    Raises:
        PermissionError: If location service is not turned on
    """
    if not get_location_service_status():
        raise PermissionError("Location service is not enabled.")
    row = _require_settings()
    return {
        "latitude": cast(float, row["latitude"]),
        "longitude": cast(float, row["longitude"]),
    }

class RetailDB(DB):
    """Database containing all retail-related data including products, users and orders"""

    products: Dict[str, Product] = Field(
        description="Dictionary of all products indexed by product ID"
    )
    users: Dict[str, User] = Field(
        description="Dictionary of all users indexed by user ID"
    )
    orders: Dict[str, Order] = Field(
        description="Dictionary of all orders indexed by order ID"
    )

    def get_statistics(self) -> dict[str, Any]:
        """Get the statistics of the database."""
        num_products = len(self.products)
        num_users = len(self.users)
        num_orders = len(self.orders)
        total_num_items = sum(
            len(product.variants) for product in self.products.values()
        )
        return {
            "num_products": num_products,
            "num_users": num_users,
            "num_orders": num_orders,
            "total_num_items": total_num_items,
        }

    @classmethod
    def load(cls, path: Optional[str] = None) -> "RetailDB":
        """Build the scoped tau2 retail tree from the unified world.db.

        Reads from normalized tables: products + rt_variants, orders +
        order_items + order_fulfillments + order_payments, users +
        rt_payment_methods. Products/orders scoped by source_skill;
        users by skill_ids_json.
        """
        conn = _connect()
        try:
            # ── Products + Variants ──────────────────────────────────
            products: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM products WHERE source_skill=?", (SOURCE_SKILL,)
            ):
                variants: Dict[str, Any] = {}
                for v in conn.execute(
                    "SELECT * FROM rt_variants WHERE product_id=?",
                    (r["product_id"],),
                ):
                    variants[v["item_id"]] = {
                        "item_id": v["item_id"],
                        "options": json.loads(_g(v, "options", "{}") or "{}"),
                        "available": bool(v["available"]),
                        "price": v["price"],
                    }
                products[r["product_id"]] = {
                    "name": r["name"],
                    "product_id": r["product_id"],
                    "variants": variants,
                }

            # ── Orders + order_items + order_fulfillments + order_payments ──
            orders_by_user: Dict[str, list] = {}
            orders: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM orders WHERE source_skill=?", (SOURCE_SKILL,)
            ):
                oid = r["order_id"]
                status = _g(r, "status", "processed")
                if status not in _TAU2_ORDER_STATUS:
                    status = "processed"
                user_id = _g(r, "customer_id")

                # Order items from normalized table
                items = []
                for oi in conn.execute(
                    "SELECT * FROM order_items WHERE order_id=?", (oid,)
                ):
                    items.append({
                        "name": _g(oi, "name", ""),
                        "product_id": oi["product_id"],
                        "item_id": _g(oi, "item_id", ""),
                        "price": oi["unit_price"],
                        "options": json.loads(_g(oi, "options", "{}") or "{}"),
                    })

                # Fulfillments from normalized table
                fulfillments = []
                for f in conn.execute(
                    "SELECT * FROM order_fulfillments WHERE order_id=?", (oid,)
                ):
                    fulfillments.append({
                        "tracking_id": json.loads(_g(f, "tracking_ids", "[]") or "[]"),
                        "item_ids": json.loads(_g(f, "item_ids", "[]") or "[]"),
                    })

                # Payment history from normalized table
                payment_history = []
                for p in conn.execute(
                    "SELECT * FROM order_payments WHERE order_id=?", (oid,)
                ):
                    payment_history.append({
                        "transaction_type": p["transaction_type"],
                        "amount": p["amount"],
                        "payment_method_id": p["payment_method_id"],
                    })

                orders[oid] = {
                    "order_id": oid,
                    "user_id": user_id,
                    "address": json.loads(_g(r, "address_json", "{}") or "{}"),
                    "items": items,
                    "status": status,
                    "fulfillments": fulfillments,
                    "payment_history": payment_history,
                    "cancel_reason": _g(r, "cancel_reason"),
                    "exchange_items": json.loads(_g(r, "exchange_items") or "null"),
                    "exchange_new_items": json.loads(
                        _g(r, "exchange_new_items") or "null"
                    ),
                    "exchange_payment_method_id": _g(r, "exchange_payment_method_id"),
                    "exchange_price_difference": _g(r, "exchange_price_difference"),
                    "return_items": json.loads(_g(r, "return_items") or "null"),
                    "return_payment_method_id": _g(r, "return_payment_method_id"),
                }
                if user_id is not None:
                    orders_by_user.setdefault(user_id, []).append(oid)

            # ── Users + rt_payment_methods ───────────────────────────
            users: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM users WHERE skill_ids_json LIKE ?",
                (f'%"{SOURCE_SKILL}"%',),
            ):
                uid = r["user_id"]
                pms: Dict[str, Any] = {}
                for pm in conn.execute(
                    "SELECT * FROM rt_payment_methods WHERE user_id=?", (uid,)
                ):
                    pms[pm["payment_method_id"]] = _build_payment_method(pm)

                users[uid] = {
                    "user_id": uid,
                    "name": _split_name(r["name"]),
                    "address": json.loads(_g(r, "address_json", "{}") or "{}"),
                    "email": r["email"],
                    "payment_methods": pms,
                    "orders": orders_by_user.get(uid, []),
                }
        finally:
            conn.close()
        return cls.model_validate(
            {"products": products, "users": users, "orders": orders}
        )

    def save(self, path: Optional[str] = None) -> None:
